      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 4
    if (cycle == 3) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b01111110;
      PI_rx_valid <= 1'b1;
      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
