      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 9
    if (cycle == 8) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b01111110;
      PI_rx_valid <= 1'b1;
      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 10
    if (cycle == 9) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b10000000;
      PI_rx_valid <= 1'b0;
      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 11
    if (cycle == 10) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b10000000;
      PI_rx_valid <= 1'b0;
      PI_legacy_idle <= 1'b1;
